const adminNav = [
  ["Dashboard","/admin/dashboard",LayoutDashboard],["Products","/admin/products",Boxes],["Categories","/admin/categories",Tags],["Orders","/admin/orders",Package],["Customers","/admin/customers",Users],["Payments","/admin/payments",CreditCard],["Receipts","/admin/receipts",CircleDollarSign],["Delivery","/admin/delivery",MapPin],["Reviews","/admin/reviews",Star],["Brand settings","/admin/settings/brand",Settings],["Payment settings","/admin/settings/payment",CreditCard],["WhatsApp settings","/admin/settings/whatsapp",MessageCircle],["Admin profile","/admin/settings/profile",Users],["Security","/admin/settings/security",Shield],
] as const;

export function AdminShell({children}:{children:ReactNode}){
  const { user, signOut } = useApp(); const navigate = useNavigate();
  const initials = user?.name.split(" ").map(s=>s[0]).join("").slice(0,2) ?? "KH";
  const out = () => { signOut(); toast("Signed out"); navigate("/admin/login", { replace: true }); };
  return <RequireAuth role="admin"><div className="min-h-screen bg-admin-bg lg:grid lg:grid-cols-[250px_1fr]"><aside className="hidden border-r bg-background p-5 lg:block"><Link to="/"><Logo/></Link><p className="mt-8 px-3 text-[10px] uppercase tracking-[.2em] text-muted-foreground">Administration</p><AdminNav/></aside><div className="min-w-0"><header className="grid h-16 grid-cols-[auto_1fr_auto_auto] items-center gap-2 border-b bg-background px-4 sm:px-7"><Sheet><SheetTrigger asChild><Button variant="ghost" size="icon" className="lg:hidden" aria-label="Open admin menu"><Menu/></Button></SheetTrigger><SheetContent side="left" className="overflow-auto"><SheetTitle><Logo/></SheetTitle><AdminNav/></SheetContent></Sheet><p className="ml-3 truncate text-xs uppercase tracking-[.15em] text-muted-foreground lg:ml-0">KH Luxury / Operations</p><Button variant="ghost" size="sm" onClick={out}><LogOut/><span className="hidden sm:inline">Sign out</span></Button><div title={user?.name} className="grid size-9 place-items-center rounded-full bg-primary font-display text-primary-foreground">{initials}</div></header><main className="p-4 sm:p-7 lg:p-10">{children}</main></div></div></RequireAuth>;
}
function AdminNav(){const {pathname:path}=useLocation();return <nav className="mt-5 grid gap-1">{adminNav.map(([label,to,Icon])=>{const active=path===to||(to!=="/admin/dashboard"&&path.startsWith(to+"/"));return <Link key={to} to={to} className={cn("flex items-center gap-3 px-3 py-2.5 text-sm text-muted-foreground hover:bg-secondary hover:text-foreground",active&&"bg-primary text-primary-foreground hover:bg-primary hover:text-primary-foreground")}><Icon className="size-4"/><span>{label}</span></Link>})}</nav>}
export function AdminTitle({title,text,action,back}:{title:string;text?:string;action?:ReactNode;back?:{to:string;label:string}}){return <div className="mb-8 grid grid-cols-[minmax(0,1fr)_auto] gap-4"><div className="min-w-0">{back?<Link to={back.to} className="eyebrow hover:text-luxury">← {back.label}</Link>:<p className="eyebrow">Admin</p>}<h1 className="mt-1 truncate font-display text-4xl">{title}</h1>{text&&<p className="mt-2 text-sm text-muted-foreground">{text}</p>}</div>{action&&<div className="shrink-0 self-end">{action}</div>}</div>}
function Status({children,tone="neutral"}:{children:ReactNode;tone?:"neutral"|"good"|"warn"|"bad"}){return <span className={cn("status whitespace-nowrap",tone==="good"&&"border-success text-success",tone==="warn"&&"border-luxury text-luxury",tone==="bad"&&"border-destructive text-destructive")}>{children}</span>}
const payTone=(s:Payment["status"])=>s==="paid"?"good":s==="rejected"?"bad":s==="awaiting_receipt"?"neutral":"warn";
function Empty({text}:{text:string}){return <div className="py-14 text-center text-sm text-muted-foreground">{text}</div>}
function Confirm({open,onOpenChange,title,text,action="Delete",onConfirm}:{open:boolean;onOpenChange:(o:boolean)=>void;title:string;text:string;action?:string;onConfirm:()=>void}){return <AlertDialog open={open} onOpenChange={onOpenChange}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle className="font-display text-2xl font-normal">{title}</AlertDialogTitle><AlertDialogDescription>{text}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Cancel</AlertDialogCancel><AlertDialogAction className="bg-destructive text-destructive-foreground hover:bg-destructive/90" onClick={onConfirm}>{action}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>}
function Field({label,children,err}:{label:string;children:ReactNode;err?:string|undefined}){return <div className="mb-5"><Label className="mb-2 block text-xs uppercase tracking-wider">{label}</Label>{children}{err&&<p className="mt-1 text-xs text-destructive">{err}</p>}</div>}

// ---------------- Dashboard ----------------
export function AdminDashboard(){
  const { products, users, orders, payments } = useApp(); const customers=users.filter(u=>u.role==="customer");
  const revenue=payments.filter(p=>p.status==="paid").reduce((n,p)=>n+p.amount,0);
  const pendingPay=payments.filter(p=>p.status==="pending_verification").length;
  const sales=useMemo(()=>{const m=new Map<string,number>();[...orders].reverse().forEach(o=>{const k=new Date(o.date).toLocaleDateString("en-GB",{month:"short"});m.set(k,(m.get(k)??0)+o.total/1e6)});return [...m].map(([m,v])=>({m,v:+v.toFixed(2)}))},[orders]);
  const statusCounts=ORDER_STEPS.map(s=>[ORDER_STEP_LABELS[s],orders.filter(o=>o.status===s).length] as const).filter(([,n])=>n>0);
  return <><AdminTitle title="Dashboard" text="A clear view of KH Luxury today."/><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[["Total products",products.length,`${products.filter(p=>p.status==="active").length} active`],["Total customers",customers.length,"Registered accounts"],["Total orders",orders.length,`${orders.filter(o=>o.status!=="delivered").length} in progress`],["Revenue",formatPrice(revenue),"Confirmed payments"],["Pending payments",pendingPay,"Awaiting verification"],["Confirmed payments",payments.filter(p=>p.status==="paid").length,"Marked paid"],["Pending orders",orders.filter(o=>["placed","payment_verification"].includes(o.status)).length,"Before confirmation"],["Completed orders",orders.filter(o=>o.status==="delivered").length,"Delivered"]].map(([l,v,n])=><div className="admin-card" key={String(l)}><p className="eyebrow">{l}</p><p className="mt-3 font-display text-4xl">{v}</p><p className="mt-2 text-xs text-muted-foreground">{n}</p></div>)}</div>
  <div className="mt-6 grid gap-6 xl:grid-cols-[1.5fr_1fr]"><section className="admin-card"><div className="flex justify-between"><div><p className="eyebrow">Sales overview</p><h2 className="mt-1 font-display text-2xl">Order value (₦m)</h2></div><BarChart3 className="text-luxury"/></div><div className="mt-8 h-64"><ResponsiveContainer width="100%" height="100%"><AreaChart data={sales}><defs><linearGradient id="sales" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--luxury)" stopOpacity={.35}/><stop offset="100%" stopColor="var(--luxury)" stopOpacity={0}/></linearGradient></defs><CartesianGrid vertical={false} stroke="var(--border)"/><XAxis dataKey="m" axisLine={false} tickLine={false}/><Tooltip/><Area type="monotone" dataKey="v" stroke="var(--luxury)" fill="url(#sales)" strokeWidth={2}/></AreaChart></ResponsiveContainer></div></section><section className="admin-card"><p className="eyebrow">Order status</p><div className="mt-6 space-y-5">{statusCounts.map(([l,n])=><div key={l}><div className="flex justify-between text-sm"><span>{l}</span><strong>{n}</strong></div><div className="mt-2 h-1.5 bg-secondary"><div className="h-full bg-luxury" style={{width:`${(n/orders.length)*100}%`}}/></div></div>)}</div></section></div>
  <div className="mt-6 grid gap-6 xl:grid-cols-[1.5fr_1fr]"><section className="admin-card"><h2 className="font-display text-2xl">Recent orders</h2><OrderTable list={orders.slice(0,5)}/></section><section className="admin-card"><h2 className="font-display text-2xl">Payment activity</h2><div className="mt-4 divide-y">{payments.slice(0,5).map(p=><Link key={p.id} to={`/admin/payments/${p.id}`} className="flex items-center justify-between py-3 text-sm hover:text-luxury"><span>{p.id}<span className="block text-xs text-muted-foreground">{formatPrice(p.amount)}</span></span><Status tone={payTone(p.status)}>{PAYMENT_LABELS[p.status]}</Status></Link>)}</div><h2 className="mt-8 font-display text-2xl">Recent customers</h2><div className="mt-4 divide-y">{customers.slice(-4).reverse().map(c=><Link key={c.id} to={`/admin/customers/${c.id}`} className="flex justify-between py-3 text-sm hover:text-luxury"><span>{c.name}</span><span className="text-xs text-muted-foreground">{formatDate(c.createdAt)}</span></Link>)}</div></section></div></>;
}

// ---------------- Products ----------------
type Filters={categories:string[];min:string;max:string;stock:string;status:string;featured:boolean;newArrival:boolean;customizable:boolean};
const noFilters:Filters={categories:[],min:"",max:"",stock:"all",status:"all",featured:false,newArrival:false,customizable:false};
export function AdminProducts(){
  const { products, categories, deleteProduct } = useApp();
  const [q,setQ]=useState(""); const [debounced,setDebounced]=useState(""); const [loading,setLoading]=useState(false);
  const [filters,setFilters]=useState<Filters>(noFilters); const [draft,setDraft]=useState<Filters>(noFilters); const [open,setOpen]=useState(false); const [toDelete,setToDelete]=useState<Product|null>(null);
  useEffect(()=>{setLoading(true);const t=setTimeout(()=>{setDebounced(q.trim().toLowerCase());setLoading(false)},250);return ()=>clearTimeout(t)},[q]);
  const activeCount=filters.categories.length+(filters.min||filters.max?1:0)+(filters.stock!=="all"?1:0)+(filters.status!=="all"?1:0)+[filters.featured,filters.newArrival,filters.customizable].filter(Boolean).length;
  const list=products.filter(p=>{
    if(debounced&&![p.name,p.category,p.id,p.sku].some(v=>v.toLowerCase().includes(debounced)))return false;
    if(filters.categories.length&&!filters.categories.includes(p.category))return false;
    if(filters.min&&p.price<Number(filters.min))return false; if(filters.max&&p.price>Number(filters.max))return false;
    if(filters.stock==="in"&&p.stock<=5)return false; if(filters.stock==="low"&&(p.stock===0||p.stock>5))return false; if(filters.stock==="out"&&p.stock>0)return false;
    if(filters.status!=="all"&&p.status!==filters.status)return false;
    if(filters.featured&&!p.featured)return false; if(filters.newArrival&&!p.newArrival)return false; if(filters.customizable&&!p.customizable)return false;
    return true;});
  return <><AdminTitle title="Products" text="Manage the collection, inventory, and merchandising." action={<Button asChild><Link to="/admin/products/new">Add product</Link></Button>}/><div className="admin-card"><div className="mb-5 grid gap-3 sm:grid-cols-[1fr_auto]"><div className="relative"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"/><Input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search by name, category, product ID or SKU" className="px-9"/>{q&&<button aria-label="Clear search" onClick={()=>setQ("")} className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"><X className="size-4"/></button>}</div>
  <Sheet open={open} onOpenChange={(o)=>{setOpen(o);if(o)setDraft(filters)}}><SheetTrigger asChild><Button variant="outline"><SlidersHorizontal/>Filter{activeCount>0&&<span className="ml-1 grid size-5 place-items-center rounded-full bg-luxury text-[10px] text-primary">{activeCount}</span>}</Button></SheetTrigger><SheetContent className="flex flex-col overflow-auto"><SheetHeader><SheetTitle className="font-display text-3xl font-normal">Filter products</SheetTitle></SheetHeader><div className="flex-1 space-y-6 px-4">
    <div><p className="eyebrow mb-3">Category</p><div className="grid grid-cols-2 gap-2">{categories.map(c=><label key={c.id} className="flex items-center gap-2 text-sm"><Checkbox checked={draft.categories.includes(c.name)} onCheckedChange={v=>setDraft(d=>({...d,categories:v?[...d.categories,c.name]:d.categories.filter(x=>x!==c.name)}))}/>{c.name}</label>)}</div></div>
    <div><p className="eyebrow mb-3">Price range (₦)</p><div className="grid grid-cols-2 gap-2"><Input type="number" min={0} placeholder="Min" value={draft.min} onChange={e=>setDraft(d=>({...d,min:e.target.value}))}/><Input type="number" min={0} placeholder="Max" value={draft.max} onChange={e=>setDraft(d=>({...d,max:e.target.value}))}/></div></div>
    <div><p className="eyebrow mb-3">Stock status</p><Select value={draft.stock} onValueChange={v=>setDraft(d=>({...d,stock:v}))}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="all">Any stock</SelectItem><SelectItem value="in">In stock (6+)</SelectItem><SelectItem value="low">Low stock (1–5)</SelectItem><SelectItem value="out">Out of stock</SelectItem></SelectContent></Select></div>
    <div><p className="eyebrow mb-3">Product status</p><Select value={draft.status} onValueChange={v=>setDraft(d=>({...d,status:v}))}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="all">Any status</SelectItem><SelectItem value="active">Active</SelectItem><SelectItem value="draft">Draft</SelectItem><SelectItem value="archived">Archived</SelectItem></SelectContent></Select></div>
    <div className="space-y-3">{(["featured","newArrival","customizable"] as const).map(k=><label key={k} className="flex items-center justify-between border-b pb-3 text-sm">{k==="newArrival"?"New arrival":k==="featured"?"Featured":"Customizable"}<Switch checked={draft[k]} onCheckedChange={v=>setDraft(d=>({...d,[k]:v}))}/></label>)}</div>
  </div><SheetFooter className="grid grid-cols-2 gap-2"><Button variant="outline" onClick={()=>{setDraft(noFilters);setFilters(noFilters);setOpen(false)}}>Clear filters</Button><Button onClick={()=>{setFilters(draft);setOpen(false)}}>Apply filters</Button></SheetFooter></SheetContent></Sheet></div>
  <div className="mb-3 flex items-center justify-between text-xs uppercase tracking-wider text-muted-foreground"><span>{list.length} of {products.length} products</span>{activeCount>0&&<button className="underline" onClick={()=>setFilters(noFilters)}>Clear filters</button>}</div>
  {loading?<div className="space-y-3">{[0,1,2].map(i=><Skeleton key={i} className="h-14 w-full"/>)}</div>:list.length===0?<Empty text={q||activeCount?"No products match your search or filters.":"No products yet. Add your first piece."}/>:<div className="overflow-x-auto"><table className="admin-table"><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody>{list.map(p=><tr key={p.id}><td><Link to={`/admin/products/${p.id}/edit`} className="flex items-center gap-3 hover:text-luxury"><img src={p.image} alt="" className="size-12 object-cover"/><span>{p.name}</span></Link></td><td className="text-xs text-muted-foreground">{p.sku}</td><td>{p.category}</td><td>{formatPrice(p.price)}</td><td>{p.stock===0?<Status tone="bad">Out</Status>:p.stock<=5?<Status tone="warn">{p.stock} low</Status>:p.stock}</td><td><Status tone={p.status==="active"?"good":"neutral"}>{p.status}</Status></td><td><div className="flex"><Button asChild variant="ghost" size="icon" aria-label="Edit"><Link to={`/admin/products/${p.id}/edit`}><Pencil/></Link></Button><Button variant="ghost" size="icon" aria-label="Delete" onClick={()=>setToDelete(p)}><Trash2/></Button></div></td></tr>)}</tbody></table></div>}</div>
  <Confirm open={!!toDelete} onOpenChange={o=>!o&&setToDelete(null)} title="Delete this product?" text={`"${toDelete?.name}" will be removed from the catalogue. Existing orders keep their records.`} onConfirm={()=>{if(toDelete){deleteProduct(toDelete.id);toast.success("Product deleted")}setToDelete(null)}}/></>;
}

const MAX_IMG=2*1024*1024;
export function ProductForm({productId}:{productId?:string}){
  const app=useApp(); const navigate=useNavigate(); const existing=productId?app.products.find(p=>p.id===productId):undefined;
  const blank={name:"",description:"",price:"",category:"",sizes:"S, M, L, XL",colors:"Obsidian, Ivory",stock:"0",featured:false,newArrival:false,customizable:false,status:"active" as ProductStatus,specifications:"",images:[] as string[]};
  const fromProduct=(p:Product)=>({name:p.name,description:p.description,price:String(p.price),category:p.category,sizes:p.sizes.join(", "),colors:p.colors.join(", "),stock:String(p.stock),featured:!!p.featured,newArrival:!!p.newArrival,customizable:!!p.customizable,status:p.status,specifications:p.specifications,images:p.images});
  const [f,setF]=useState(existing?fromProduct(existing):blank); const [errors,setErrors]=useState<Record<string,string>>({}); const [saving,setSaving]=useState(false);
  const replaceIdx=useRef<number|null>(null); const fileRef=useRef<HTMLInputElement>(null);
  useEffect(()=>{if(existing)setF(fromProduct(existing))},[existing?.id]); // eslint-disable-line react-hooks/exhaustive-deps
  if(productId&&app.ready&&!existing)return <><AdminTitle title="Product not found" back={{to:"/admin/products",label:"Products"}}/><Empty text="This product does not exist or was deleted."/></>;
  const set=<K extends keyof typeof f>(k:K,v:(typeof f)[K])=>setF(s=>({...s,[k]:v}));
  const onFiles=async(files:FileList|null)=>{if(!files?.length)return;const out:string[]=[];for(const file of Array.from(files)){if(!file.type.startsWith("image/")){toast.error(`${file.name} is not an image`);continue}if(file.size>MAX_IMG){toast.error(`${file.name} is larger than 2 MB`);continue}out.push(await readFileAsDataUrl(file))}
    if(!out.length)return; const idx=replaceIdx.current; replaceIdx.current=null;
    setF(s=>{if(idx!==null){const imgs=[...s.images];imgs[idx]=out[0]!;return {...s,images:imgs}}const imgs=[...s.images,...out].slice(0,6);if(s.images.length+out.length>6)toast("A maximum of 6 images is kept");return {...s,images:imgs}}); if(fileRef.current)fileRef.current.value="";};
  const submit=async(e:FormEvent)=>{e.preventDefault();const er:Record<string,string>={};const price=Number(f.price),stock=Number(f.stock);const sizes=f.sizes.split(",").map(s=>s.trim()).filter(Boolean),colors=f.colors.split(",").map(s=>s.trim()).filter(Boolean);
    if(f.name.trim().length<2)er["name"]="Enter a product name"; if(f.description.trim().length<10)er["description"]="Add a description (at least 10 characters)"; if(!(price>0))er["price"]="Enter a valid price"; if(!f.category)er["category"]="Choose a category"; if(!f.images.length)er["images"]="Upload at least one image"; if(!sizes.length)er["sizes"]="Add at least one size"; if(!colors.length)er["colors"]="Add at least one color"; if(!Number.isInteger(stock)||stock<0)er["stock"]="Stock must be 0 or more";
    setErrors(er); if(Object.keys(er).length){toast.error("Please complete the highlighted fields");return}
    setSaving(true); await new Promise(r=>setTimeout(r,400));
    const id=existing?.id??(f.name.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,"")+"-"+Math.random().toString(36).slice(2,5));
    app.saveProduct({id,sku:existing?.sku??`KH-${id.slice(0,3).toUpperCase()}-${Date.now().toString().slice(-5)}`,name:f.name.trim(),description:f.description.trim(),price,category:f.category,image:f.images[0]!,images:f.images,sizes,colors,stock,featured:f.featured,newArrival:f.newArrival,customizable:f.customizable,status:f.status,specifications:f.specifications.trim(),createdAt:existing?.createdAt??new Date().toISOString()});
    toast.success(existing?"Product updated":"Product created"); navigate("/admin/products");};
  return <><AdminTitle title={existing?"Edit product":"Create new product"} text="Product details and storefront presentation." back={{to:"/admin/products",label:"Products"}}/><form noValidate className="grid gap-6 xl:grid-cols-[1fr_340px]" onSubmit={submit}><div className="admin-card">
    <Field label="Product name" err={errors["name"]}><Input value={f.name} onChange={e=>set("name",e.target.value)} maxLength={100}/></Field>
    <Field label="Description" err={errors["description"]}><Textarea className="min-h-32" value={f.description} onChange={e=>set("description",e.target.value)} maxLength={1000}/></Field>
    <div className="grid gap-x-5 sm:grid-cols-2"><Field label="Price (₦)" err={errors["price"]}><Input type="number" min={0} value={f.price} onChange={e=>set("price",e.target.value)}/></Field><Field label="Category" err={errors["category"]}><Select value={f.category} onValueChange={v=>set("category",v)}><SelectTrigger><SelectValue placeholder="Choose category"/></SelectTrigger><SelectContent>{app.categories.map(c=><SelectItem key={c.id} value={c.name}>{c.name}{!c.active?" (inactive)":""}</SelectItem>)}</SelectContent></Select></Field></div>
    <Field label={`Product images (${f.images.length}/6)`} err={errors["images"]}><div className="grid grid-cols-3 gap-3 sm:grid-cols-4">{f.images.map((src,i)=><div key={i} className="group relative aspect-square border bg-secondary"><img src={src} alt={`Product ${i+1}`} className="h-full w-full object-cover"/>{i===0&&<span className="absolute left-1 top-1 bg-background px-1.5 text-[9px] uppercase">Cover</span>}<div className="absolute inset-x-1 bottom-1 flex gap-1 opacity-100 sm:opacity-0 sm:group-hover:opacity-100"><Button type="button" size="sm" variant="secondary" className="h-7 flex-1 px-1 text-[10px]" onClick={()=>{replaceIdx.current=i;fileRef.current?.click()}}><RefreshCw className="size-3"/>Replace</Button><Button type="button" size="icon" variant="secondary" className="size-7" aria-label="Remove image" onClick={()=>set("images",f.images.filter((_,j)=>j!==i))}><X className="size-3"/></Button></div></div>)}{f.images.length<6&&<button type="button" onClick={()=>{replaceIdx.current=null;fileRef.current?.click()}} className="grid aspect-square place-items-center border border-dashed border-luxury bg-secondary/50 text-xs text-muted-foreground"><span className="grid place-items-center gap-1"><ImagePlus className="size-5 text-luxury"/>Add images</span></button>}</div><input ref={fileRef} type="file" accept="image/*" multiple className="sr-only" onChange={e=>onFiles(e.target.files)}/><p className="mt-2 text-xs text-muted-foreground">JPG, PNG or WebP · up to 2 MB each · first image is the cover.</p></Field>
    <div className="grid gap-x-5 sm:grid-cols-3"><Field label="Sizes (comma separated)" err={errors["sizes"]}><Input value={f.sizes} onChange={e=>set("sizes",e.target.value)}/></Field><Field label="Colors (comma separated)" err={errors["colors"]}><Input value={f.colors} onChange={e=>set("colors",e.target.value)}/></Field><Field label="Stock quantity" err={errors["stock"]}><Input type="number" min={0} value={f.stock} onChange={e=>set("stock",e.target.value)}/></Field></div>
    <Field label="Specifications"><Textarea value={f.specifications} onChange={e=>set("specifications",e.target.value)} placeholder="Fabric, fit, care, origin…" maxLength={600}/></Field>
  </div><aside className="admin-card h-fit"><Field label="Product status"><Select value={f.status} onValueChange={v=>set("status",v as ProductStatus)}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="active">Active — visible in store</SelectItem><SelectItem value="draft">Draft — hidden</SelectItem><SelectItem value="archived">Archived — hidden</SelectItem></SelectContent></Select></Field>{(["featured","newArrival","customizable"] as const).map(k=><div key={k} className="mb-4 flex items-center justify-between border-b pb-4"><Label>{k==="featured"?"Featured product":k==="newArrival"?"New arrival":"Customizable / Blank tee"}</Label><Switch checked={f[k]} onCheckedChange={v=>set(k,v)}/></div>)}<Button type="submit" className="w-full" disabled={saving}>{saving?"Saving…":"Save product"}</Button><div className="mt-2 grid grid-cols-2 gap-2"><Button type="button" variant="outline" onClick={()=>navigate("/admin/products")}>Cancel</Button><Button type="button" variant="ghost" onClick={()=>{setF(existing?fromProduct(existing):blank);setErrors({})}}>Reset</Button></div></aside></form></>;
}

// ---------------- Categories ----------------
export function AdminCategories(){
  const { categories, products, saveCategory, deleteCategory, uid } = useApp();
  const [edit,setEdit]=useState<Category|null>(null); const [open,setOpen]=useState(false); const [del,setDel]=useState<Category|null>(null);
  const count=(n:string)=>products.filter(p=>p.category===n).length;
  return <><AdminTitle title="Categories" text="Organise how the collection is browsed." action={<Button onClick={()=>{setEdit(null);setOpen(true)}}>Add category</Button>}/><div className="admin-card">{categories.length===0?<Empty text="No categories yet."/>:categories.map(c=><div key={c.id} className="grid grid-cols-[auto_1fr_auto] items-center gap-4 border-b py-4 last:border-0">{c.image?<img src={c.image} alt="" className="size-12 object-cover"/>:<div className="grid size-12 place-items-center bg-secondary"><Tags className="size-4 text-luxury"/></div>}<div className="min-w-0"><p className="flex items-center gap-2">{c.name}{!c.active&&<Status>Inactive</Status>}</p><p className="truncate text-xs text-muted-foreground">{count(c.name)} products · {c.description}</p></div><div className="flex"><Button variant="ghost" size="sm" onClick={()=>{setEdit(c);setOpen(true)}}>Edit</Button><Button variant="ghost" size="sm" onClick={()=>setDel(c)}>Delete</Button></div></div>)}</div>
  <CategoryDialog open={open} onOpenChange={setOpen} category={edit} names={categories.filter(c=>c.id!==edit?.id).map(c=>c.name.toLowerCase())} onSave={(c)=>{saveCategory({...c,id:edit?.id??uid("cat")});toast.success(edit?"Category updated":"Category added");setOpen(false)}}/>
  <Confirm open={!!del} onOpenChange={o=>!o&&setDel(null)} title="Delete category" text={del&&count(del.name)>0?`"${del.name}" has ${count(del.name)} product(s) assigned. Reassign them to another category first.`:"Are you sure you want to delete this category?"} action={del&&count(del.name)>0?"Understood":"Delete"} onConfirm={()=>{if(del&&count(del.name)===0){deleteCategory(del.id);toast.success("Category deleted")}else toast.error("Category still has products and was not deleted");setDel(null)}}/></>;
}
function CategoryDialog({open,onOpenChange,category,names,onSave}:{open:boolean;onOpenChange:(o:boolean)=>void;category:Category|null;names:string[];onSave:(c:Omit<Category,"id">)=>void}){
  const [f,setF]=useState({name:"",description:"",image:"" as string,active:true}); const [err,setErr]=useState("");
  useEffect(()=>{if(open){setF({name:category?.name??"",description:category?.description??"",image:category?.image??"",active:category?.active??true});setErr("")}},[open,category]);
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent><DialogHeader><DialogTitle className="font-display text-3xl font-normal">{category?"Edit category":"Add category"}</DialogTitle><DialogDescription>Categories appear in the shop filters.</DialogDescription></DialogHeader><form noValidate onSubmit={e=>{e.preventDefault();const n=f.name.trim();if(n.length<2)return setErr("Enter a category name");if(names.includes(n.toLowerCase()))return setErr("A category with this name already exists");onSave({name:n,description:f.description.trim(),active:f.active,...(f.image?{image:f.image}:{})})}}>
    <Field label="Category name" err={err}><Input value={f.name} maxLength={50} onChange={e=>setF(s=>({...s,name:e.target.value}))}/></Field>
    <Field label="Description"><Textarea value={f.description} maxLength={300} onChange={e=>setF(s=>({...s,description:e.target.value}))}/></Field>
    <Field label="Image (optional)"><div className="flex items-center gap-3">{f.image&&<img src={f.image} alt="" className="size-14 object-cover"/>}<Input type="file" accept="image/*" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>MAX_IMG){toast.error("Image must be under 2 MB");return;}const url=await readFileAsDataUrl(file);setF(s=>({...s,image:url}))}}/>{f.image&&<Button type="button" variant="ghost" size="icon" onClick={()=>setF(s=>({...s,image:""}))}><X/></Button>}</div></Field>
    <div className="flex items-center justify-between border-y py-4"><Label>Active</Label><Switch checked={f.active} onCheckedChange={v=>setF(s=>({...s,active:v}))}/></div>
    <DialogFooter className="mt-6"><Button type="button" variant="outline" onClick={()=>onOpenChange(false)}>Cancel</Button><Button type="submit">{category?"Save changes":"Add category"}</Button></DialogFooter></form></DialogContent></Dialog>;
}

// ---------------- Delivery ----------------
export function AdminDelivery(){
  const { locations, saveLocation, deleteLocation, uid } = useApp();
  const [edit,setEdit]=useState<DeliveryLocation|null>(null); const [open,setOpen]=useState(false); const [del,setDel]=useState<DeliveryLocation|null>(null);
  return <><AdminTitle title="Delivery locations" text="Only active locations are offered at checkout." action={<Button onClick={()=>{setEdit(null);setOpen(true)}}>Add location</Button>}/>{locations.length===0?<div className="admin-card"><Empty text="No delivery locations yet."/></div>:<div className="grid gap-4 md:grid-cols-2">{locations.map(l=><div className={cn("admin-card",!l.active&&"opacity-70")} key={l.id}><div className="flex justify-between gap-4"><div className="min-w-0"><h2 className="font-display text-2xl">{l.name}</h2><p className="mt-1 text-sm">{l.address}</p><p className="mt-2 text-sm text-muted-foreground">{l.fee?formatPrice(l.fee):"Free"} · {l.eta}</p><p className="mt-2 text-xs text-muted-foreground">{l.description}</p></div><div className="text-right"><Switch checked={l.active} aria-label="Active" onCheckedChange={v=>{saveLocation({...l,active:v});toast.success(`${l.name} is now ${v?"active":"inactive"}`)}}/><p className="mt-1 text-[10px] uppercase tracking-wider text-muted-foreground">{l.active?"Active":"Inactive"}</p></div></div><div className="mt-6 flex gap-2"><Button variant="outline" size="sm" onClick={()=>{setEdit(l);setOpen(true)}}>Edit</Button><Button variant="ghost" size="sm" onClick={()=>setDel(l)}>Delete</Button></div></div>)}</div>}
  <LocationDialog open={open} onOpenChange={setOpen} location={edit} onSave={l=>{saveLocation({...l,id:edit?.id??uid("loc")});toast.success(edit?"Location updated":"Location added");setOpen(false)}}/>
  <Confirm open={!!del} onOpenChange={o=>!o&&setDel(null)} title="Delete location" text="Are you sure you want to delete this delivery location?" onConfirm={()=>{if(del){deleteLocation(del.id);toast.success("Location deleted")}setDel(null)}}/></>;
}
function LocationDialog({open,onOpenChange,location,onSave}:{open:boolean;onOpenChange:(o:boolean)=>void;location:DeliveryLocation|null;onSave:(l:Omit<DeliveryLocation,"id">)=>void}){
  const [f,setF]=useState({name:"",address:"",description:"",fee:"",eta:"",active:true}); const [er,setEr]=useState<Record<string,string>>({});
  useEffect(()=>{if(open){setF({name:location?.name??"",address:location?.address??"",description:location?.description??"",fee:location?String(location.fee):"",eta:location?.eta??"",active:location?.active??true});setEr({})}},[open,location]);
  const s=(k:keyof typeof f)=>(e:{target:{value:string}})=>setF(x=>({...x,[k]:e.target.value}));
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[90vh] overflow-auto"><DialogHeader><DialogTitle className="font-display text-3xl font-normal">{location?"Edit location":"Add location"}</DialogTitle><DialogDescription>Customers choose from active locations at checkout.</DialogDescription></DialogHeader><form noValidate onSubmit={e=>{e.preventDefault();const x:Record<string,string>={};if(f.name.trim().length<2)x["name"]="Enter a location name";if(f.address.trim().length<3)x["address"]="Enter an address";if(f.fee===""||Number(f.fee)<0)x["fee"]="Enter a fee (0 for free)";if(!f.eta.trim())x["eta"]="Add an estimated delivery time";setEr(x);if(Object.keys(x).length)return;onSave({name:f.name.trim(),address:f.address.trim(),description:f.description.trim(),fee:Number(f.fee),eta:f.eta.trim(),active:f.active})}}>
    <Field label="Location name" err={er["name"]}><Input value={f.name} onChange={s("name")} maxLength={60}/></Field><Field label="Address" err={er["address"]}><Input value={f.address} onChange={s("address")} maxLength={160}/></Field><Field label="Description"><Textarea value={f.description} onChange={s("description")} maxLength={300}/></Field>
    <div className="grid gap-x-4 sm:grid-cols-2"><Field label="Delivery fee (₦)" err={er["fee"]}><Input type="number" min={0} value={f.fee} onChange={s("fee")}/></Field><Field label="Estimated delivery" err={er["eta"]}><Input value={f.eta} onChange={s("eta")} placeholder="1–3 working days"/></Field></div>
    <div className="flex items-center justify-between border-y py-4"><Label>Active</Label><Switch checked={f.active} onCheckedChange={v=>setF(x=>({...x,active:v}))}/></div>
    <DialogFooter className="mt-6"><Button type="button" variant="outline" onClick={()=>onOpenChange(false)}>Cancel</Button><Button type="submit">{location?"Save changes":"Add location"}</Button></DialogFooter></form></DialogContent></Dialog>;
}

// ---------------- Reviews ----------------
export function AdminReviews(){
  const { reviews, products, users, setReviewStatus } = useApp(); const [tab,setTab]=useState("all");
  const list=reviews.filter(r=>tab==="all"||r.status===tab);
  const tone=(s:string)=>s==="approved"?"good":s==="hidden"||s==="rejected"?"bad":"warn";
  return <><AdminTitle title="Reviews" text="Only approved reviews are visible to customers."/><div className="mb-5 flex flex-wrap gap-2">{["all","pending","approved","hidden"].map(t=><Button key={t} size="sm" variant={tab===t?"default":"outline"} onClick={()=>setTab(t)} className="capitalize">{t} ({t==="all"?reviews.length:reviews.filter(r=>r.status===t).length})</Button>)}</div>{list.length===0?<div className="admin-card"><Empty text="No reviews in this view."/></div>:<div className="grid gap-4">{list.map(r=>{const c=users.find(u=>u.id===r.customerId);const pr=products.find(p=>p.id===r.productId);return <div className="admin-card" key={r.id}><div className="flex flex-wrap justify-between gap-3"><div><p className="font-medium">{c?<Link to={`/admin/customers/${c.id}`} className="hover:text-luxury">{c.name}</Link>:"Unknown"}</p><p className="text-xs text-muted-foreground">{pr?.name??"Removed product"} · {formatDate(r.date)}</p><div className="mt-1 flex text-luxury">{Array.from({length:5}).map((_,j)=><Star key={j} className={cn("size-3",j<r.rating&&"fill-current")}/>)}</div></div><Status tone={tone(r.status)}>{r.status}</Status></div><p className="mt-4 text-sm text-muted-foreground">{r.text}</p>{r.image&&<img src={r.image} alt="Review attachment" className="mt-3 size-24 object-cover"/>}<div className="mt-5 flex gap-2">{r.status!=="approved"&&<Button size="sm" onClick={()=>{setReviewStatus(r.id,"approved");toast.success("Review approved and now visible")}}><Eye/>{r.status==="hidden"?"Show review":"Approve"}</Button>}{r.status!=="hidden"&&<Button size="sm" variant="outline" onClick={()=>{setReviewStatus(r.id,"hidden");toast("Review hidden from customers")}}><EyeOff/>Hide</Button>}</div></div>})}</div>}</>;
}

// ---------------- Orders ----------------
function OrderTable({list}:{list:Order[]}){const { users, payments } = useApp();if(!list.length)return <Empty text="No orders yet."/>;return <div className="overflow-x-auto"><table className="admin-table"><thead><tr><th>Order ID</th><th>Customer</th><th>Date</th><th>Amount</th><th>Payment</th><th>Status</th><th></th></tr></thead><tbody>{list.map(o=>{const pay=payments.find(p=>p.id===o.paymentId);const c=users.find(u=>u.id===o.customerId);return <tr key={o.id}><td><Link to={`/admin/orders/${o.id}`} className="font-medium underline-offset-4 hover:text-luxury hover:underline">#{o.id}</Link></td><td>{c?<Link to={`/admin/customers/${c.id}`} className="hover:text-luxury">{c.name}</Link>:o.contact.name}</td><td>{formatDate(o.date)}</td><td>{formatPrice(o.total)}</td><td>{pay&&<Status tone={payTone(pay.status)}>{PAYMENT_LABELS[pay.status]}</Status>}</td><td className="whitespace-nowrap">{ORDER_STEP_LABELS[o.status]}</td><td><Button asChild variant="ghost" size="sm"><Link to={`/admin/orders/${o.id}`}>View details<ChevronRight/></Link></Button></td></tr>})}</tbody></table></div>}
export function AdminOrders(){const { orders } = useApp();const [q,setQ]=useState("");const [st,setSt]=useState("all");const list=orders.filter(o=>(st==="all"||o.status===st)&&(o.id+o.contact.name).toLowerCase().includes(q.toLowerCase()));return <><AdminTitle title="Orders" text="Track fulfilment, payment, and delivery."/><div className="admin-card"><div className="mb-5 grid gap-3 sm:grid-cols-[1fr_220px]"><Input placeholder="Search order ID or customer" value={q} onChange={e=>setQ(e.target.value)}/><Select value={st} onValueChange={setSt}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="all">All statuses</SelectItem>{ORDER_STEPS.map(s=><SelectItem key={s} value={s}>{ORDER_STEP_LABELS[s]}</SelectItem>)}</SelectContent></Select></div><OrderTable list={list}/></div></>}
export function Timeline({status}:{status:OrderStatus}){const idx=ORDER_STEPS.indexOf(status);return <div>{ORDER_STEPS.map((s,i)=><div key={s} className="grid grid-cols-[28px_1fr] gap-3"><div className="flex flex-col items-center"><span className={cn("grid size-6 place-items-center rounded-full border",i<=idx?"border-luxury bg-luxury text-primary":"border-border")}>{i<=idx&&<Check className="size-3"/>}</span>{i<ORDER_STEPS.length-1&&<span className={cn("h-8 w-px",i<idx?"bg-luxury":"bg-border")}/>}</div><p className={cn("pt-1 text-sm",i===idx?"font-semibold":i>idx&&"text-muted-foreground")}>{ORDER_STEP_LABELS[s]}</p></div>)}</div>}
export function ReceiptView({payment}:{payment:Payment}){const [zoom,setZoom]=useState(false);const r=payment.receipt;if(!r)return <p className="mt-3 text-sm text-muted-foreground">No receipt uploaded yet.</p>;const isPdf=r.type==="application/pdf";
  const open=()=>{const w=window.open();if(w){w.document.title=r.name;w.document.body.style.margin="0";w.document.body.innerHTML=isPdf?`<iframe src="${r.dataUrl}" style="border:0;width:100vw;height:100vh"></iframe>`:`<img src="${r.dataUrl}" style="max-width:100%;display:block;margin:auto">`}};
  return <div className="mt-3">{isPdf?<div className="border bg-secondary p-4 text-sm">PDF receipt · {r.name}</div>:<button type="button" onClick={()=>setZoom(true)} className="group relative block w-full border bg-secondary"><img src={r.dataUrl} alt={`Receipt for ${payment.orderId}`} className="mx-auto max-h-80 object-contain"/><span className="absolute right-2 top-2 grid size-8 place-items-center bg-background/90"><ZoomIn className="size-4"/></span></button>}<p className="mt-2 text-xs text-muted-foreground">{r.name} · uploaded {formatDate(r.uploadedAt)}</p><div className="mt-3 flex gap-2">{!isPdf&&<Button size="sm" variant="outline" onClick={()=>setZoom(true)}><ZoomIn/>View</Button>}<Button size="sm" variant="outline" onClick={open}><ExternalLink/>Open</Button></div><Dialog open={zoom} onOpenChange={setZoom}><DialogContent className="max-w-4xl"><DialogHeader><DialogTitle className="font-display text-2xl font-normal">Receipt · {payment.id}</DialogTitle></DialogHeader><div className="max-h-[75vh] overflow-auto"><img src={r.dataUrl} alt="Receipt full size" className="mx-auto w-full max-w-2xl"/></div></DialogContent></Dialog></div>}
function Items({order}:{order:Order}){return <>{order.items.map((it,i)=><div key={i} className="mt-5 flex gap-4 border-t pt-5"><img src={it.image} className="size-16 object-cover" alt=""/><div className="min-w-0 flex-1"><p>{it.name}</p><p className="text-xs text-muted-foreground">{it.color} / {it.size} · Qty {it.quantity} · {formatPrice(it.price)} each</p>{it.customization&&<div className="mt-2 border-l-2 border-luxury pl-3 text-xs"><p><strong>Customization:</strong> {it.customization.blank}</p>{it.customization.instructions&&<p className="text-muted-foreground">“{it.customization.instructions}”</p>}{it.customization.designData&&<a href={it.customization.designData} download={it.customization.designName} className="mt-2 inline-flex items-center gap-2 underline">{it.customization.designData.startsWith("data:image")&&<img src={it.customization.designData} alt="Custom design" className="size-12 border object-contain"/>}Download design ({it.customization.designName})</a>}</div>}</div><span className="text-sm">{formatPrice(it.price*it.quantity)}</span></div>)}</>}
function Totals({order}:{order:Order}){return <div className="space-y-2 text-sm"><Row l="Subtotal" v={formatPrice(order.subtotal)}/><Row l="VAT (7.5%)" v={formatPrice(order.vat)}/><Row l="Delivery fee" v={order.deliveryFee?formatPrice(order.deliveryFee):"Free"}/><div className="border-t pt-2 font-semibold"><Row l="Total" v={formatPrice(order.total)}/></div></div>}
function Row({l,v}:{l:string;v:ReactNode}){return <div className="flex justify-between gap-4"><span className="text-muted-foreground">{l}</span><span className="text-right">{v}</span></div>}
export function AdminOrderDetail({orderId}:{orderId:string}){
  const { orders, payments, users, setOrderStatus, ready } = useApp(); const o=orders.find(x=>x.id===orderId); const [next,setNext]=useState<OrderStatus|"">("");
  if(!o)return ready?<><AdminTitle title="Order not found" back={{to:"/admin/orders",label:"Orders"}}/><Empty text="This order does not exist."/></>:null;
  const pay=payments.find(p=>p.id===o.paymentId); const c=users.find(u=>u.id===o.customerId);
  const locked=pay?.status!=="paid"; const allowed=ORDER_STEPS.filter((s,i)=>locked?i<=2:i>=2);
  return <><AdminTitle title={`Order #${o.id}`} text={`Placed ${formatDate(o.date)}`} back={{to:"/admin/orders",label:"Orders"}}/><div className="grid gap-6 xl:grid-cols-[1fr_360px]"><div className="space-y-6"><section className="admin-card"><h2 className="font-display text-2xl">Products</h2><Items order={o}/><div className="mt-6 border-t pt-5"><Totals order={o}/></div></section><section className="admin-card"><h2 className="font-display text-2xl">Payment receipt</h2>{pay?<><div className="mt-3 flex items-center justify-between"><Link to={`/admin/payments/${pay.id}`} className="text-sm underline hover:text-luxury">{pay.id}</Link><Status tone={payTone(pay.status)}>{PAYMENT_LABELS[pay.status]}</Status></div><ReceiptView payment={pay}/></>:<Empty text="No payment record."/>}</section></div>
  <aside className="space-y-6"><section className="admin-card"><h2 className="font-display text-2xl">Status</h2><div className="mt-5"><Timeline status={o.status}/></div><div className="mt-6 border-t pt-5"><Label className="mb-2 block text-xs uppercase tracking-wider">Update order status</Label><Select value={next||o.status} onValueChange={v=>setNext(v as OrderStatus)}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{allowed.map(s=><SelectItem key={s} value={s}>{ORDER_STEP_LABELS[s]}</SelectItem>)}</SelectContent></Select>{locked&&<p className="mt-2 text-xs text-muted-foreground">Fulfilment steps unlock once payment is confirmed.</p>}<Button className="mt-3 w-full" disabled={!next||next===o.status} onClick={()=>{if(next){setOrderStatus(o.id,next);toast.success(`Order marked: ${ORDER_STEP_LABELS[next]}`);setNext("")}}}>Update order</Button></div></section>
  <section className="admin-card"><h2 className="font-display text-2xl">Customer</h2><div className="mt-4 space-y-2 text-sm"><Row l="Name" v={c?<Link to={`/admin/customers/${c.id}`} className="underline">{o.contact.name}</Link>:o.contact.name}/><Row l="Email" v={o.contact.email}/><Row l="Phone" v={o.contact.phone}/></div></section>
  <section className="admin-card"><h2 className="font-display text-2xl">Delivery</h2><div className="mt-4 space-y-2 text-sm"><Row l="Address" v={`${o.delivery.address}, ${o.delivery.city}, ${o.delivery.state}`}/><Row l="Location" v={o.delivery.locationName}/><Row l="Expected" v={formatDate(o.expectedDelivery)}/></div></section></aside></div></>;
}

// ---------------- Customers ----------------
export function AdminCustomers(){const { users, orders, payments } = useApp();const [q,setQ]=useState("");const list=users.filter(u=>u.role==="customer"&&(u.name+u.email+u.id).toLowerCase().includes(q.toLowerCase()));return <><AdminTitle title="Customers" text="Customer activity and order value."/><div className="admin-card"><Input className="mb-5" placeholder="Search name, email or customer ID" value={q} onChange={e=>setQ(e.target.value)}/>{list.length===0?<Empty text="No customers found."/>:<div className="overflow-x-auto"><table className="admin-table"><thead><tr><th>Customer</th><th>ID</th><th>Email</th><th>Orders</th><th>Total spent</th><th></th></tr></thead><tbody>{list.map(c=>{const os=orders.filter(o=>o.customerId===c.id);const spent=payments.filter(p=>p.customerId===c.id&&p.status==="paid").reduce((n,p)=>n+p.amount,0);return <tr key={c.id}><td><Link to={`/admin/customers/${c.id}`} className="hover:text-luxury">{c.name}</Link></td><td className="text-xs text-muted-foreground">{c.id}</td><td>{c.email}</td><td>{os.length}</td><td>{formatPrice(spent)}</td><td><Button asChild variant="ghost" size="sm"><Link to={`/admin/customers/${c.id}`}>View details<ChevronRight/></Link></Button></td></tr>})}</tbody></table></div>}</div></>}
export function AdminCustomerDetail({customerId}:{customerId:string}){
  const { users, orders, payments, reviews, products, ready } = useApp(); const c=users.find(u=>u.id===customerId&&u.role==="customer");
  if(!c)return ready?<><AdminTitle title="Customer not found" back={{to:"/admin/customers",label:"Customers"}}/><Empty text="This customer does not exist."/></>:null;
  const os=orders.filter(o=>o.customerId===c.id); const ps=payments.filter(p=>p.customerId===c.id); const rs=reviews.filter(r=>r.customerId===c.id);
  const spent=ps.filter(p=>p.status==="paid").reduce((n,p)=>n+p.amount,0);
  return <><AdminTitle title={c.name} text={`Customer ${c.id}`} back={{to:"/admin/customers",label:"Customers"}}/><div className="grid gap-6 xl:grid-cols-[340px_1fr]"><aside className="admin-card h-fit space-y-2 text-sm"><h2 className="mb-4 font-display text-2xl">Profile</h2><Row l="Email" v={c.email}/><Row l="Phone" v={c.phone}/><Row l="Joined" v={formatDate(c.createdAt)}/><Row l="Status" v={<Status tone={c.status==="active"?"good":"bad"}>{c.status}</Status>}/><Row l="Orders" v={os.length}/><Row l="Total spent" v={formatPrice(spent)}/></aside><div className="space-y-6"><section className="admin-card"><h2 className="font-display text-2xl">Order history</h2><OrderTable list={os}/></section><section className="admin-card"><h2 className="font-display text-2xl">Payment history</h2>{ps.length===0?<Empty text="No payments."/>:<div className="mt-3 divide-y">{ps.map(p=><Link key={p.id} to={`/admin/payments/${p.id}`} className="flex items-center justify-between py-3 text-sm hover:text-luxury"><span>{p.id} · #{p.orderId}<span className="block text-xs text-muted-foreground">{formatDate(p.date)} · {formatPrice(p.amount)}</span></span><Status tone={payTone(p.status)}>{PAYMENT_LABELS[p.status]}</Status></Link>)}</div>}</section><section className="admin-card"><h2 className="font-display text-2xl">Reviews submitted</h2>{rs.length===0?<Empty text="No reviews."/>:rs.map(r=><div key={r.id} className="mt-4 border-t pt-4 text-sm"><div className="flex justify-between"><span>{products.find(p=>p.id===r.productId)?.name??"Product"} · {r.rating}★</span><Status>{r.status}</Status></div><p className="mt-1 text-muted-foreground">{r.text}</p></div>)}</section></div></div></>;
}

// ---------------- Payments & receipts (one data source) ----------------
export function AdminPayments({view}:{view:"payments"|"receipts"}){
  const { payments, users } = useApp(); const [st,setSt]=useState(view==="receipts"?"pending_verification":"all"); const [q,setQ]=useState("");
  const list=payments.filter(p=>(view==="payments"||p.receipt)&&(st==="all"||p.status===st)&&(p.id+p.orderId).toLowerCase().includes(q.toLowerCase()));
  return <><AdminTitle title={view==="payments"?"Payments":"Payment receipts"} text={view==="payments"?"All bank-transfer payments and their verification status.":"Uploaded receipts awaiting or past review — same records as Payments."}/><div className="admin-card"><div className="mb-5 grid gap-3 sm:grid-cols-[1fr_220px]"><Input placeholder="Search payment or order ID" value={q} onChange={e=>setQ(e.target.value)}/><Select value={st} onValueChange={setSt}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="all">All statuses</SelectItem>{Object.entries(PAYMENT_LABELS).map(([k,v])=><SelectItem key={k} value={k}>{v}</SelectItem>)}</SelectContent></Select></div>{list.length===0?<Empty text="No payments in this view."/>:<div className="overflow-x-auto"><table className="admin-table"><thead><tr><th>Payment ID</th><th>Order</th><th>Customer</th><th>Amount</th><th>Date</th><th>Receipt</th><th>Status</th><th></th></tr></thead><tbody>{list.map(p=><tr key={p.id}><td><Link to={`/admin/payments/${p.id}`} className="font-medium hover:text-luxury hover:underline">{p.id}</Link></td><td><Link to={`/admin/orders/${p.orderId}`} className="hover:text-luxury">#{p.orderId}</Link></td><td>{users.find(u=>u.id===p.customerId)?.name}</td><td>{formatPrice(p.amount)}</td><td>{formatDate(p.date)}</td><td>{p.receipt?<Link to={`/admin/payments/${p.id}`} className="underline">View receipt</Link>:<span className="text-xs text-muted-foreground">None</span>}</td><td><Status tone={payTone(p.status)}>{PAYMENT_LABELS[p.status]}</Status></td><td><Button asChild variant="ghost" size="icon" aria-label="Details"><Link to={`/admin/payments/${p.id}`}><ChevronRight/></Link></Button></td></tr>)}</tbody></table></div>}</div></>;
}
export function AdminPaymentDetail({paymentId}:{paymentId:string}){
  const { payments, orders, users, paymentAction, ready } = useApp(); const p=payments.find(x=>x.id===paymentId);
  const [dialog,setDialog]=useState<null|"reject"|"resubmit"|"confirm">(null); const [note,setNote]=useState("");
  if(!p)return ready?<><AdminTitle title="Payment not found" back={{to:"/admin/payments",label:"Payments"}}/><Empty text="This payment does not exist."/></>:null;
  const o=orders.find(x=>x.id===p.orderId); const c=users.find(u=>u.id===p.customerId);
  const act=()=>{if(!dialog)return;paymentAction(p.id,dialog,note.trim().slice(0,300)||undefined);toast.success(dialog==="confirm"?"Payment confirmed — order can proceed":dialog==="reject"?"Payment rejected":"New receipt requested");setDialog(null);setNote("")};
  return <><AdminTitle title={`Payment ${p.id}`} text={`For order #${p.orderId}`} back={{to:"/admin/payments",label:"Payments"}} action={<Status tone={payTone(p.status)}>{PAYMENT_LABELS[p.status]}</Status>}/><div className="grid gap-6 xl:grid-cols-[1fr_360px]"><div className="space-y-6"><section className="admin-card"><h2 className="font-display text-2xl">Payment receipt</h2><ReceiptView payment={p}/></section>{o&&<section className="admin-card"><div className="flex items-center justify-between"><h2 className="font-display text-2xl">Order information</h2><Button asChild variant="outline" size="sm"><Link to={`/admin/orders/${o.id}`}>Open order</Link></Button></div><Items order={o}/><div className="mt-6 border-t pt-5"><Totals order={o}/></div></section>}</div>
  <aside className="space-y-6"><section className="admin-card"><h2 className="font-display text-2xl">Actions</h2><p className="mt-2 text-xs text-muted-foreground">Only an admin confirmation marks a payment as paid.</p><div className="mt-4 grid gap-2"><Button disabled={p.status==="paid"||!p.receipt} onClick={()=>setDialog("confirm")}><Check/>Confirm payment</Button><Button variant="outline" disabled={p.status==="paid"||p.status==="rejected"} onClick={()=>setDialog("reject")}><X/>Reject payment</Button><Button variant="ghost" disabled={p.status==="paid"} onClick={()=>setDialog("resubmit")}><RefreshCw/>Request new receipt</Button></div></section>
  <section className="admin-card space-y-2 text-sm"><h2 className="mb-3 font-display text-2xl">Details</h2><Row l="Amount" v={formatPrice(p.amount)}/><Row l="Payment date" v={formatDate(p.date)}/><Row l="Customer" v={c?<Link to={`/admin/customers/${c.id}`} className="underline">{c.name}</Link>:"—"}/><Row l="Email" v={c?.email}/><Row l="Phone" v={c?.phone}/>{o&&<><Row l="Order status" v={ORDER_STEP_LABELS[o.status]}/><Row l="Delivery" v={`${o.delivery.locationName} · ${o.delivery.address}`}/></>}</section>
  <section className="admin-card"><h2 className="font-display text-2xl">Payment notes</h2>{p.notes.length===0?<p className="mt-3 text-sm text-muted-foreground">No notes yet.</p>:<ul className="mt-3 space-y-3 text-sm">{[...p.notes].reverse().map((n,i)=><li key={i} className="border-l-2 border-luxury pl-3"><p>{n.text}</p><p className="text-xs text-muted-foreground">{new Date(n.at).toLocaleString("en-GB")}</p></li>)}</ul>}</section></aside></div>
  <Dialog open={!!dialog} onOpenChange={o=>{if(!o){setDialog(null);setNote("")}}}><DialogContent><DialogHeader><DialogTitle className="font-display text-3xl font-normal">{dialog==="confirm"?"Confirm payment":dialog==="reject"?"Reject payment":"Request new receipt"}</DialogTitle><DialogDescription>{dialog==="confirm"?`Mark ${formatPrice(p.amount)} as paid. The order moves to Payment confirmed.`:"The customer will see this status and your note on their order."}</DialogDescription></DialogHeader>{dialog!=="confirm"&&<Field label={dialog==="reject"?"Reason (optional)":"Message to customer (optional)"}><Textarea value={note} maxLength={300} onChange={e=>setNote(e.target.value)} placeholder={dialog==="reject"?"e.g. Amount does not match the order total":"e.g. The receipt image is unreadable"}/></Field>}<DialogFooter><Button variant="outline" onClick={()=>setDialog(null)}>Cancel</Button><Button variant={dialog==="reject"?"destructive":"default"} onClick={act}>{dialog==="confirm"?"Confirm payment":dialog==="reject"?"Reject payment":"Request receipt"}</Button></DialogFooter></DialogContent></Dialog></>;
}

// ---------------- Settings ----------------
export function AdminGeneric({view}:{view:string}){const title=view.split("-").map(s=>s.charAt(0).toUpperCase()+s.slice(1)).join(" ");return <SettingsForm title={title}/>}
function SettingsForm({title}:{title:string}){const fields=title.includes("Payment")?["Account name","Bank name","Account number","Payment instructions"]:title.includes("WhatsApp")?["WhatsApp number","Default greeting","Business hours"]:title.includes("Security")?["Current password","New password","Confirm new password"]:title.includes("Profile")?["Full name","Email","Phone"]:["Brand name","Contact email","Brand statement","Instagram handle"];return <><AdminTitle title={title} text="Changes are stored in preview state only."/><form className="admin-card max-w-2xl" onSubmit={e=>{e.preventDefault();toast.success("Settings saved")}}>{fields.map(f=><Field key={f} label={f}>{f.includes("instructions")||f.includes("statement")?<Textarea/>:<Input type={f.toLowerCase().includes("password")?"password":"text"}/>}</Field>)}<Button className="mt-6">Save changes</Button></form></>}
